package fraymus.workspace;

import fraymus.geometry.*;
import org.json.*;
import java.util.*;
import java.security.MessageDigest;
import java.nio.charset.StandardCharsets;

/** Java owns procedural data. The model selects bounded inputs, never coordinates or success flags. */
final class Procedural {
    static final String PROCEDURE="procedural-space-v1",VERSION="geometry-core-v1";
    static final String SCOPE="Seeded procedural geometry in abstract units. Projections and slices are views of mathematical data, not higher-dimensional physical measurements.";
    static int integer(JSONObject in,String key,int fallback,int low,int high){Object raw=in.opt(key);if(raw==null)return fallback;if(!(raw instanceof Number n)||!Double.isFinite(n.doubleValue())||n.doubleValue()!=n.intValue()||n.intValue()<low||n.intValue()>high)throw new IllegalArgumentException(key+" needs an integer in "+low+".."+high);return n.intValue();}
    static JSONObject definition(JSONObject input){
        SpatialScene.keys(input,"type","dimensions","seed","samples","iterations","step","influence","kill","side","rooms");String type=input.optString("type","colonization");if(!Set.of("colonization","dungeon").contains(type))throw new IllegalArgumentException("Choose colonization or dungeon");int d=integer(input,"dimensions",type.equals("dungeon")?2:3,2,type.equals("dungeon")?4:16),seed=integer(input,"seed",2701,0,1_000_000_000);
        var result=new JSONObject().put("type",type).put("dimensions",d).put("seed",seed).put("version",VERSION);
        if(type.equals("colonization")){for(String k:List.of("side","rooms"))if(input.has(k))throw new IllegalArgumentException("Dungeon-only field "+k);for(String k:List.of("step","influence","kill"))if(input.has(k)&&!(input.get(k) instanceof Number))throw new IllegalArgumentException("Use numeric "+k);var s=new Colonization.Spec(d,seed,integer(input,"samples",128,16,512),integer(input,"iterations",64,1,128),input.optDouble("step",.035),input.optDouble("influence",.3),input.optDouble("kill",.055));result.put("samples",s.attractors()).put("iterations",s.iterations()).put("step",s.step()).put("influence",s.influence()).put("kill",s.kill());}
        else{for(String k:List.of("samples","iterations","step","influence","kill"))if(input.has(k))throw new IllegalArgumentException("Colony-only field "+k);var s=new Dungeon.Spec(d,seed,integer(input,"side",d==2?24:d==3?18:12,12,40),integer(input,"rooms",12,4,24));result.put("side",s.side()).put("rooms",s.rooms());}return result;
    }
    static JSONObject inputDefinition(JSONObject stored){var in=new JSONObject(stored.toString());if(!VERSION.equals(in.remove("version")))throw new IllegalArgumentException("Unsupported procedural algorithm version");return definition(in);}
    static String codeIdentity(){try{var digest=MessageDigest.getInstance("SHA-256");for(String name:List.of("NDSpace","Colonization","Colonization$Spec","Colonization$Node","Colonization$Result","Dungeon","Dungeon$Spec","Dungeon$Box","Dungeon$Corridor","Dungeon$Result")){try(var stream=NDSpace.class.getResourceAsStream(name+".class")){if(stream==null)throw new IllegalStateException("Missing bundled geometry class "+name);digest.update(name.getBytes(StandardCharsets.UTF_8));digest.update(stream.readAllBytes());}}return HexFormat.of().formatHex(digest.digest());}catch(Exception e){throw new IllegalStateException("Geometry implementation identity unavailable",e);}}
    static JSONObject compute(JSONObject raw){
        var d=inputDefinition(raw);int dimensions=d.getInt("dimensions");var nodes=new JSONArray();var parents=new JSONArray();var extra=new JSONObject();var metrics=new JSONObject().put("dimensions",dimensions).put("seed",d.getInt("seed"));
        if(d.getString("type").equals("colonization")){
            var r=Colonization.grow(new Colonization.Spec(dimensions,d.getInt("seed"),d.getInt("samples"),d.getInt("iterations"),d.getDouble("step"),d.getDouble("influence"),d.getDouble("kill")));var generations=new JSONArray();for(var n:r.nodes()){nodes.put(new JSONArray(n.position()));parents.put(n.parent());generations.put(n.generation());}var targets=new JSONArray();for(var p:r.attractors())targets.put(new JSONArray(p));extra.put("generations",generations).put("attractors",targets).put("consumedBy",new JSONArray(r.consumedBy())).put("growth",new JSONArray(r.growth()));int consumed=(int)r.consumedBy().stream().filter(x->x>=0).count();metrics.put("vertices",nodes.length()).put("edges",nodes.length()-1).put("consumed",consumed).put("remaining",r.attractors().size()-consumed).put("stopReason",r.stopReason()).put("connected",true).put("stepLength",r.spec().step());
        }else{
            var r=Dungeon.generate(new Dungeon.Spec(dimensions,d.getInt("seed"),d.getInt("side"),d.getInt("rooms")));var indices=new HashMap<Integer,Integer>();for(int cell:r.floor()){indices.put(cell,nodes.length());nodes.put(new JSONArray(Dungeon.decode(cell,r.spec().side(),dimensions)));}var rooms=new JSONArray();for(var room:r.rooms())rooms.put(new JSONObject().put("low",new JSONArray(room.low())).put("high",new JSONArray(room.high())));var corridors=new JSONArray();for(var c:r.corridors())corridors.put(new JSONObject().put("from",c.from()).put("to",c.to()).put("cells",new JSONArray(c.cells())));extra.put("rooms",rooms).put("corridors",corridors).put("floorIds",new JSONArray(r.floor())).put("pathIds",new JSONArray(r.path())).put("path",new JSONArray(r.path().stream().map(indices::get).toList())).put("side",r.spec().side());metrics.put("vertices",nodes.length()).put("rooms",r.rooms().size()).put("corridors",r.corridors().size()).put("reachable",r.reachable()).put("pathSteps",r.path().size()-1).put("connected",r.reachable()==nodes.length());
        }
        metrics.put("verified",true).put("passed",true);return new JSONObject().put("definition",d).put("nodes",nodes).put("parents",parents).put("extra",extra).put("metrics",metrics).put("scope",SCOPE);
    }
    static JSONArray projections(JSONObject data){
        int dimensions=data.getJSONObject("definition").getInt("dimensions"),side=data.getJSONObject("extra").optInt("side",1);var nodes=data.getJSONArray("nodes");var result=new JSONArray();
        for(int angle:new int[]{0,30,60,90}){var raw=new ArrayList<double[]>();double minX=Double.POSITIVE_INFINITY,minY=minX,maxX=Double.NEGATIVE_INFINITY,maxY=maxX;
            for(Object o:nodes){var row=(JSONArray)o;double[] p=new double[dimensions];for(int k=0;k<dimensions;k++)p[k]=row.getDouble(k)/(side>1?side-1:1);var xy=NDSpace.project(p,0,dimensions-1,angle);raw.add(xy);minX=Math.min(minX,xy[0]);maxX=Math.max(maxX,xy[0]);minY=Math.min(minY,xy[1]);maxY=Math.max(maxY,xy[1]);}
            double span=Math.max(.1,Math.max(maxX-minX,maxY-minY));var points=new JSONArray();for(var p:raw)points.put(new JSONArray(List.of(round(400+700*(p[0]-(minX+maxX)/2)/span),round(250-420*(p[1]-(minY+maxY)/2)/span))));result.put(new JSONObject().put("angle",angle).put("axisA",0).put("axisB",dimensions-1).put("points",points));
        }return result;
    }
    static double round(double x){return StrictMath.rint(x*1_000_000)/1_000_000;}
    static JSONObject data(JSONObject g){var data=g.getJSONObject("proceduralResult");if(!MeasurementStore.hash(data.toString()).equals(g.getString("proceduralSha256"))||!codeIdentity().equals(g.getString("proceduralCodeSha256"))||!data.getJSONObject("definition").similar(g.getJSONObject("proceduralDefinition")))throw new IllegalStateException("Frozen procedural source or implementation changed");return data;}
    static void verify(JSONObject g){var data=data(g);if(!compute(g.getJSONObject("proceduralDefinition")).similar(data))throw new IllegalStateException("Procedural result differs from independently reconstructed source");}
    static JSONArray checks(JSONObject g){
        var data=data(g);int count=data.getJSONArray("nodes").length(),dim=data.getJSONObject("definition").getInt("dimensions");var checks=new JSONArray().put(new JSONObject().put("selector","#source-count").put("expectText",String.valueOf(count))).put(new JSONObject().put("selector","#dimensions").put("expectText",dim+"D")).put(new JSONObject().put("selector","#verification").put("expectText","Java invariants passed")).put(new JSONObject().put("selector","#angle").put("expectText","0°")).put(new JSONObject().put("selector","#rotate").put("action","click")).put(new JSONObject().put("selector","#angle").put("expectText","30°")).put(new JSONObject().put("selector","#reset").put("action","click")).put(new JSONObject().put("selector","#visible-count").put("expectText",String.valueOf(count)));
        if(dim>2)checks.put(new JSONObject().put("selector","#slice").put("action","click")).put(new JSONObject().put("selector","#slice-state").put("expectText",sliceLabel(data)));
        checks.put(new JSONObject().put("selector","#reset").put("action","click")).put(new JSONObject().put("selector","#angle").put("expectText","0°")).put(new JSONObject().put("selector","#visible-count").put("expectText",String.valueOf(count))).put(new JSONObject().put("selector","#scope").put("expectText",SCOPE));return checks;
    }
    static String sliceLabel(JSONObject data){int d=data.getJSONObject("definition").getInt("dimensions"),bins=data.getJSONObject("extra").optInt("side",8);return "Axis "+(d-1)+" · bin "+(bins/2);}
    static JSONObject verifyView(JSONObject g,JSONObject actual){
        SpatialScene.keys(actual,"points","angle","slice");var expected=projections(data(g)).getJSONObject(0).getJSONArray("points");var points=actual.getJSONArray("points");if(points.length()!=expected.length()||!actual.getString("angle").equals("0°")||!actual.getString("slice").equals("All"))throw new IllegalStateException("Actual procedural view does not show the complete reset source");double maximum=0;for(int i=0;i<points.length();i++){var p=points.getJSONObject(i);SpatialScene.keys(p,"index","x","y");if(p.getInt("index")!=i)throw new IllegalStateException("Rendered point identity/order changed");double error=Math.max(Math.abs(p.getDouble("x")-expected.getJSONArray(i).getDouble(0)),Math.abs(p.getDouble("y")-expected.getJSONArray(i).getDouble(1)));if(!Double.isFinite(error))throw new IllegalStateException("Nonfinite actual projection");maximum=Math.max(maximum,error);}if(maximum>.002)throw new IllegalStateException("Rendered procedural coordinates exceed0.002 SVG units");return new JSONObject().put("passed",true).put("vertices",points.length()).put("maxError",maximum).put("report",g.getJSONObject("report"));
    }
}
